<section class="page-content">
	<div class="container">
		<div class="ann-filter" role="tablist">
			<?php $first = true; foreach ( array_keys( $events ) as $year ) : ?>
				<button type="button" class="ann-filter-btn<?php echo $first ? ' is-active' : ''; ?>" data-year="<?php echo esc_attr( $year ); ?>"><?php echo esc_html( $year ); ?></button>
			<?php $first = false; endforeach; ?>
		</div>

		<?php $first = true; foreach ( $events as $year => $items ) : ?>
			<div class="fin-panel ann-list" data-year="<?php echo esc_attr( $year ); ?>"<?php echo $first ? '' : ' hidden'; ?>>
				<?php foreach ( $items as $item ) :
					$day   = $item[0];
					$month = '';
					if ( preg_match( '/^(\d{1,2})\s+(.+)$/u', $item[0], $m ) ) {
						$day   = $m[1];
						$month = $m[2];
					}
					$lines = array_filter( array_map( 'trim', explode( '<br>', $item[1] ) ) );
					?>
					<article class="ann-item">
						<div class="ann-date">
							<span class="ann-date-day"><?php echo esc_html( $day ); ?></span>
							<?php if ( $month ) : ?><span class="ann-date-year"><?php echo esc_html( $month ); ?></span><?php endif; ?>
						</div>
						<div class="ann-body">
							<?php foreach ( $lines as $line ) : ?>
								<p><?php echo wp_kses_post( $line ); ?></p>
							<?php endforeach; ?>
						</div>
					</article>
				<?php endforeach; ?>
			</div>
		<?php $first = false; endforeach; ?>
	</div>
</section>

